const lead = $json;
const daysSince = parseInt(lead.days_since_created) || 0;
const daysSinceContact = parseInt(lead.days_since_contact) || 0;

let message = '';

if (daysSince <= 3) {
  message = `Hi ${lead.name}! 👋 Just checking in — did you get a chance to think about what we discussed?\n\nWe have limited seats this batch. Reply YES to know more! 🎯`;
} else if (daysSince <= 7) {
  message = `Hi ${lead.name}! 🌟 Our counsellor would love to speak with you for just 10 minutes.\n\nShall I schedule a free call? Reply YES and your preferred time 📞`;
} else if (daysSince <= 14) {
  message = `Hi ${lead.name}! 🎉 Last chance — our special scholarship batch is almost full!\n\nOnly a few seats remain. Want to secure yours? Reply INTERESTED 🔥`;
} else {
  message = `Hi ${lead.name}! We miss you 😊\n\nOur new batch starts soon. Want to know about our latest offers? Reply YES!`;
}

return [{ json: { ...lead, dripMessage: message } }];

